import {askName} from './name-dialog.js';
import {locations,selectLocation,addLocation,exportBoulder,importBoulder,readBoulder} from './locations.js';
import './mobile-focus.js';
import {routeFace} from './route-face.js';
import {holdPreview,nextPending} from './classification.js';
import {createOnRock} from './on-rock.js';
import {editContour} from './contour-editor.js';
import {holdPath,nextHoldName,removeFace} from './geometry.js';
import {createHoldDetection} from './hold-detection-ui.js';
import {withoutExisting} from './hold-detection.js';
import {freshState,id,setRole,allowedHolds,footHolds,validateRoute,validateState} from './core.js';
import {readState,writeState} from './storage.js';
import {CameraSession} from './camera.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=freshState(),faceId=null,selected=null,view='wall',tool='select',history=[],draft=null,editorFace=null,role='hand',sessionId=null,sessionFace=null,persistence=Promise.resolve(),toastTimer,storageFailed=false;
const camera = new CameraSession({video:$('#camera-video'),overlay:$('#camera-overlay'),status:$('#camera-status')});
let generationHistory=[],generationIndex=-1;
let saveSequence=0, editorZoom=100, lastGeneration=null;
const qualityColors={unknown:'#e6d9c1',good:'#99dba4',medium:'#f3d574',bad:'#f39887'};
const roleLabels={startL:'Saída E',startR:'Saída D',hand:'Mão',foot:'Pé',finishL:'Final E',finishR:'Final D',remove:'Retirar'};
const typeOptions=['Não informado','Batente','Reglete','Abaulado','Pinça','Buraco','Outro'];
const options=(list,value)=>list.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('');
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4200);}
async function confirmAction(title,copy){$('#confirm-title').textContent=title;$('#confirm-copy').textContent=copy;const dialog=$('#confirm-dialog');dialog.returnValue='cancel';dialog.showModal();return new Promise(resolve=>dialog.addEventListener('close',()=>resolve(dialog.returnValue==='ok'),{once:true}));}
function persist(){const snapshot=structuredClone(state),sequence=++saveSequence;$('#save-state').textContent='Salvando…';persistence=persistence.catch(()=>{}).then(()=>writeState(snapshot));return persistence.then(()=>{if(sequence===saveSequence)$('#save-state').textContent='Salvo neste aparelho';return true;},()=>{if(sequence===saveSequence)$('#save-state').textContent='Falha ao salvar — exporte um backup';toast('Falha no armazenamento. As alterações estão apenas na memória; exporte um backup.');return false;});}
function checkpoint(){history.push(structuredClone(state.wall));if(history.length>10)history.shift();$('#undo').disabled=false;}
function wallChanged(){state.wall.revision++;persist();renderWall();renderCounts();}
function rememberPosition(){
 const pageX=window.scrollX,pageY=window.scrollY,positions=$$('dialog,.stage').map(el=>[el,el.scrollLeft,el.scrollTop]);
 const active=document.activeElement,key=active?.dataset?.id,roleKey=active?.dataset?.role,activeId=active?.id,parent=active?.closest('.stage,dialog');
 return ()=>{let focus=active?.isConnected?active:activeId?document.getElementById(activeId):null;
 if(!focus&&parent?.isConnected)focus=[...parent.querySelectorAll('[data-id],[data-role]')].find(el=>key?el.dataset.id===key:roleKey&&el.dataset.role===roleKey);
 if(!focus?.matches?.('input,textarea,select'))focus?.focus?.({preventScroll:true});for(const [el,x,y]of positions){el.scrollLeft=x;el.scrollTop=y;}window.scrollTo({left:pageX,top:pageY,behavior:'instant'});};
}
function renderCounts(){renderLocationSelector();$('#wall-title').textContent=state.wall.name;$('#hold-count').textContent=state.wall.holds.length;$('#route-count').textContent=state.routes.filter(r=>r.snapshot.id===state.wall.id).length;}
function switchView(next){if(next!=='session')stopCamera();view=next;$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===next));for(const v of ['wall','routes','session'])$(`#${v}-view`).hidden=v!==next;const headings={wall:['1 · CADASTRE E CLASSIFIQUE','Meu muro'],routes:['2 · ESCOLHA OU GERE','Meus boulders'],session:['3 · LEIA E ESCALE','Sessão']};$('#page-eyebrow').textContent=headings[next][0];$('#page-title').textContent=headings[next][1];if(next==='wall')renderWall();if(next==='routes')renderRoutes();if(next==='session')renderSession();}
function tabs(target,faces,active,handler){$(target).innerHTML=faces.map(f=>`<button type="button" data-id="${f.id}" class="${active===f.id?'active':''}">${esc(f.name)}</button>`).join('')||'<span class="help">Faces do muro</span>';$(target).querySelectorAll('button').forEach(b=>b.onclick=()=>handler(b.dataset.id));}
function labelFor(list){const tags=[];if(list.includes('startL')||list.includes('startR'))tags.push('S '+[list.includes('startL')?'E':'',list.includes('startR')?'D':''].filter(Boolean).join('+'));if(list.includes('finishL')||list.includes('finishR'))tags.push('F '+[list.includes('finishL')?'E':'',list.includes('finishR')?'D':''].filter(Boolean).join('+'));if(list.includes('foot'))tags.push('P');if(!tags.length&&list.includes('hand'))tags.push('M');return tags.join(' / ');}
function board(target,wall,active,{route=null,dim=0,onHold=null,onBlank=null,zoom=100}={}){
 const host=$(target),scrollTop=host.scrollTop,scrollLeft=host.scrollLeft,face=wall.faces.find(f=>f.id===active);if(!face){host.innerHTML='<div class="empty-state"><h3>Nenhuma face por aqui.</h3><p>Cadastre uma face no seu muro para começar.</p></div>';return;}
 const width=1000,height=1000/face.aspect,holds=wall.holds.filter(h=>h.faceId===active),allowed=route?allowedHolds(route):null;
 const maskId='mask-'+target.replace(/\W/g,'');
 const circles=holds.filter(h=>allowed?.has(h.id)).map(h=>`<path d="${holdPath(h,width,height)}" fill="black"/>`).join('');
 host.innerHTML=`<div class="photo-board" style="width:${zoom}%;aspect-ratio:${face.aspect};--face-aspect:${face.aspect}"><img alt="${esc(face.name)}" src="${face.photo}" draggable="false"><svg viewBox="0 0 ${width} ${height}" role="group" aria-label="Agarras em ${esc(face.name)}"><defs><mask id="${maskId}"><rect width="100%" height="100%" fill="white"/>${circles}</mask></defs>${dim?`<rect width="100%" height="100%" fill="black" opacity="${dim/100}" mask="url(#${maskId})" pointer-events="none"/>`:''}${holds.filter(h=>!route||onHold||allowed.has(h.id)).map(h=>{const list=route?.assignments[h.id]??[],active=route?allowed.has(h.id):true;const color=route?(list.some(r=>r.startsWith('start'))?'#99dba4':list.some(r=>r.startsWith('finish'))?'#f39887':list.includes('foot')?'#7ed9ea':'#f5c177'):h.footOnly?'#7ed9ea':qualityColors[h.quality];const label=route?labelFor(list)||(active?'P':''):h.name+(h.footOnly?' · P':'');return `<g class="hold-target ${h.id===selected&&!route?'is-editing':''}" data-id="${h.id}" tabindex="${onHold?'0':'-1'}" role="${onHold?'button':'img'}" aria-label="${esc(h.name)}${list.length?' — '+esc(label):''}"><path d="${holdPath(h,width,height)}" fill="transparent" stroke="${active?color:'#ffffff35'}" stroke-width="${h.id===selected&&!route?4:2}"/><text x="${h.x*width}" y="${h.y*height-h.radius*width-9}" text-anchor="middle" font-size="19">${esc(label)}</text></g>`;}).join('')}</svg></div>`;
 host.scrollTop=scrollTop;host.scrollLeft=scrollLeft;
 host.querySelectorAll('.hold-target').forEach(g=>{const invoke=e=>{e.preventDefault();e.stopPropagation();onHold?.(g.dataset.id)};g.onclick=invoke;g.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')invoke(e)}});
 host.querySelector('svg').onclick=e=>{if(!onBlank)return;const rect=e.currentTarget.getBoundingClientRect();onBlank((e.clientX-rect.left)/rect.width,(e.clientY-rect.top)/rect.height);};
}
function renderWall(){
 const restorePosition=rememberPosition();
 if(!state.wall.faces.some(f=>f.id===faceId))faceId=state.wall.faces[0]?.id;
 tabs('#face-tabs',state.wall.faces,faceId,value=>{faceId=value;selected=null;$('#zoom').value=100;renderWall()});
 if(state.wall.faces.length)board('#wall-stage',state.wall,faceId,{zoom:Number($('#zoom').value),onHold:key=>{selected=key;tool='select';renderWall();},onBlank:(x,y)=>{if(tool!=='add'||x<0||y<0||x>1||y>1)return;if(state.wall.holds.length>=5000){toast('Limite de 5000 agarras.');return;}checkpoint();const newName=nextHoldName(state.wall.holds,faceId);const h={id:id(),faceId,x,y,radius:.025,name:newName,quality:'unknown',type:'Não informado',color:'',direction:0,match:false};state.wall.holds.push(h);selected=h.id;wallChanged();}});
 else {$('#wall-stage').innerHTML='<div class="empty-state"><h3>Cadastre seu muro.</h3><p>Uma foto por face. Depois, marque as agarras.</p><button id="first-face" class="primary">+ Adicionar primeira face</button></div>';$('#first-face').onclick=addFace;}
 $('#tool-select').classList.toggle('active',tool==='select');$('#tool-add').classList.toggle('active',tool==='add');$('#tool-add').disabled=!faceId;$('#detect-holds').disabled=!faceId;
 $('#stage-hint').textContent=tool==='add'?'Toque no centro de uma agarra. Ajuste o tamanho ao lado.':'Selecione uma agarra para editar. Use zoom para detalhes.';
 renderInspector();restorePosition();
}
function renderInspector(){const panel=$('#inspector'),h=state.wall.holds.find(h=>h.id===selected),face=state.wall.faces.find(f=>f.id===faceId);
 if(!h){panel.innerHTML=`<div class="eyebrow">${face?'A FACE ATUAL':'CADASTRO'}</div><h3>${face?esc(face.name):'Comece pela foto.'}</h3>${face?`<span class="badge">${face.angle}°</span><span class="badge">${face.width} × ${face.height} m</span><div class="stat">${state.wall.holds.filter(h=>h.faceId===face.id).length}</div><p>agarras cadastradas nesta face</p><button id="inspector-add" class="primary">+ Marcar agarras</button><button id="renumber-face" class="quiet">Renumerar agarras desta face</button><button id="delete-face" class="danger">Excluir face</button><button id="face-rename" class="quiet">Editar nome e medidas</button><hr><p>Cada boulder guarda sua montagem. As alterações aqui valem para os próximos projetos.</p>`:'<div class="info-list"><span><b>01</b> Adicione uma foto</span><span><b>02</b> Cadastre as agarras</span><span><b>03</b> Monte um boulder</span></div>'}`;
 if(face){$('#renumber-face').onclick=async()=>{if(await confirmAction('Renumerar esta face?','Os nomes das agarras desta face serão A1, A2, A3… Boulders já salvos mantêm seus nomes.')){checkpoint();state.wall.holds.filter(h=>h.faceId===face.id).forEach((h,i)=>h.name='A'+(i+1));wallChanged();}};$('#delete-face').onclick=async()=>{const count=state.wall.holds.filter(h=>h.faceId===face.id).length;if(await confirmAction('Excluir esta face?',face.name+' e suas '+count+' agarras serão removidas do muro atual. Boulders salvos permanecem. Você pode Desfazer enquanto estiver nesta sessão.')){checkpoint();removeFace(state.wall,face.id);faceId=null;selected=null;wallChanged();}};$('#inspector-add').onclick=()=>{tool='add';renderWall()};$('#face-rename').onclick=()=>editFace(face);}return;}
 panel.innerHTML=`<div class="eyebrow">AGARRA / ${esc(face.name)}</div><button id="back-face" type="button">← Voltar à face</button><div class="classification-focus"><h3>${esc(h.name)}</h3><div id="hold-detail"></div><button id="locate-hold" type="button">Localizar na parede</button></div><div id="quick-quality" class="role-tools"></div><div id="quick-type" class="role-tools"></div><form id="hold-form"><label>Uso da agarra<select name="footOnly"><option value="false" ${!h.footOnly?'selected':''}>Mãos e pés</option><option value="true" ${h.footOnly?'selected':''}>Somente pé</option></select></label><label>Nome / número<input name="name" maxlength="50" required value="${esc(h.name)}"></label><label>Qualidade percebida<select name="quality"><option value="unknown" ${h.quality==='unknown'?'selected':''}>○ Não classificada</option><option value="good" ${h.quality==='good'?'selected':''}>● Boa</option><option value="medium" ${h.quality==='medium'?'selected':''}>◆ Média</option><option value="bad" ${h.quality==='bad'?'selected':''}>▲ Ruim</option></select></label><label>Tipo<select name="type">${options(typeOptions,h.type)}</select></label><details class="advanced"><summary>Posição, tamanho e outros detalhes</summary><label>Cor física<input name="color" maxlength="40" placeholder="Ex.: azul, madeira" value="${esc(h.color)}"></label><label>Tamanho da marcação<input name="radius" type="range" min="8" max="100" value="${h.radius*1000}" style="width:100%"></label><div class="form-row"><label>Posição X (%)<input name="x" type="number" min="0" max="100" step="0.01" value="${(h.x*100).toFixed(2)}" required></label><label>Posição Y (%)<input name="y" type="number" min="0" max="100" step="0.01" value="${(h.y*100).toFixed(2)}" required></label></div><label>Direção da puxada (°)<input name="direction" type="number" min="0" max="360" value="${h.direction}" required></label><p class="help">0° para cima · 90° direita · 180° baixo · 270° esquerda, na foto.</p></details><label class="check"><input name="match" type="checkbox" ${h.match?'checked':''}>Cabe juntar as duas mãos</label><button class="primary">Salvar agarra</button></form><button id="next-unclassified" class="quiet">Próxima sem classificação →</button><button id="edit-contour" class="quiet">Ajustar contorno</button><button id="delete-hold" class="danger">Excluir agarra</button><p class="help">Boulders já salvos preservam esta agarra em sua montagem.</p>`;
 holdPreview($('#hold-detail'),face,h);
 panel.insertBefore($('#next-unclassified'),$('#quick-quality'));
 const quickForm=$('#hold-form');quickForm.prepend(quickForm.elements.match.closest('label'));quickForm.prepend(quickForm.elements.footOnly.closest('label'));quickForm.elements.match.disabled=!!h.footOnly;
 quickForm.elements.quality.closest('label').hidden=true;quickForm.elements.type.closest('label').hidden=true;
 $('#locate-hold').onclick=()=>$('#wall-stage').querySelector('.is-editing')?.scrollIntoView({block:'center',inline:'center',behavior:'smooth'});
 $('#back-face').onclick=()=>{selected=null;tool='select';renderWall();};
 const saveHold=async(render=false)=>{const form=$('#hold-form');if(!form.checkValidity())return;const f=new FormData(form),name=f.get('name').trim();if(!name){toast('Preencha o nome da agarra.');return;}checkpoint();if(h.contour){const dx=Number(f.get('x'))/100-h.x,dy=Number(f.get('y'))/100-h.y;h.contour=h.contour.map(([x,y])=>[Math.max(0,Math.min(1,x+dx)),Math.max(0,Math.min(1,y+dy))]);}Object.assign(h,{name,quality:f.get('quality'),type:f.get('type'),color:f.get('color').trim(),radius:Number(f.get('radius'))/1000,direction:Number(f.get('direction')),footOnly:f.get('footOnly')==='true',match:f.get('footOnly')!=='true'&&f.has('match'),x:Number(f.get('x'))/100,y:Number(f.get('y'))/100});state.wall.revision++;const saved=await persist();if(render){renderWall();renderCounts();if(saved)toast('Agarra salva.');}};
 for(const [target,field,choices]of [['#quick-quality','quality',[['good','Boa'],['medium','Média'],['bad','Ruim'],['unknown','Não sei']]],['#quick-type','type',typeOptions.map(t=>[t,t])]]){const host=$(target);host.innerHTML=choices.map(([v,label])=>`<button type="button" data-value="${esc(v)}" class="${h[field]===v?'active':''}">${esc(label)}</button>`).join('');host.querySelectorAll('button').forEach(b=>b.onclick=async()=>{$('#hold-form').elements[field].value=b.dataset.value;await saveHold(false);host.querySelectorAll('button').forEach(el=>el.classList.toggle('active',el===b));});}
 $('#next-unclassified').onclick=async()=>{if(!$('#hold-form').reportValidity())return;await saveHold(false);const next=nextPending(state.wall.holds,h);if(next){selected=next.id;renderWall();}else toast('Nenhuma outra agarra sem classificação nesta face.');};
 $('#hold-form').onsubmit=e=>{e.preventDefault();saveHold(true)};
 $('#hold-form').onchange=e=>{if(e.target.name==='direction')h.directionKnown=true;const form=$('#hold-form');form.elements.match.disabled=form.elements.footOnly.value==='true';if(form.elements.match.disabled)form.elements.match.checked=false;saveHold(false);};
 $('#hold-form [name=radius]').oninput=e=>{const shape=$('#wall-stage').querySelector(`[data-id="${h.id}"] path`);if(shape)shape.setAttribute('d',holdPath({...h,radius:Number(e.target.value)/1000},1000,1000/face.aspect));};
 $('#edit-contour').onclick=async()=>{const points=await editContour(face,h);if(points){checkpoint();h.contour=points;h.x=points.reduce((s,p)=>s+p[0],0)/points.length;h.y=points.reduce((s,p)=>s+p[1],0)/points.length;wallChanged();}};
 $('#delete-hold').onclick=async()=>{if(await confirmAction('Remover esta agarra?',`${h.name} sai do cadastro atual. Seus boulders salvos permanecem intactos.`)){checkpoint();state.wall.holds=state.wall.holds.filter(x=>x.id!==h.id);selected=null;wallChanged();}};
}
function editFace(face){const dialog=$('#face-dialog'),form=$('#face-form');form.reset();form.elements.name.value=face.name;form.elements.width.value=face.width;form.elements.height.value=face.height;form.elements.angle.value=face.angle;form.elements.photo.required=false;form.elements.photo.disabled=true;form.dataset.edit=face.id;$('#face-submit').textContent='Salvar face';dialog.showModal();}
function addFace(){if(state.wall.faces.length>=30){toast('Limite de 30 faces por acervo.');return;}const form=$('#face-form');form.reset();delete form.dataset.edit;form.elements.photo.required=true;form.elements.photo.disabled=false;$('#face-submit').textContent='Adicionar face';$('#face-dialog').showModal();}
async function processPhoto(file){if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>20*1024*1024)throw Error('Escolha JPG, PNG ou WebP com até 20 MB.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,2000/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return {photo:canvas.toDataURL('image/jpeg',.88),aspect:canvas.width/canvas.height};}
$('#face-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,button=$('#face-submit'),f=new FormData(form);button.disabled=true;try{const edit=form.dataset.edit;const picture=edit?null:await processPhoto(f.get('photo'));checkpoint();if(edit)Object.assign(state.wall.faces.find(x=>x.id===edit),{name:f.get('name').trim(),width:Number(f.get('width')),height:Number(f.get('height')),angle:Number(f.get('angle'))});else{const face={id:id(),name:f.get('name').trim(),width:Number(f.get('width')),height:Number(f.get('height')),angle:Number(f.get('angle')),...picture};state.wall.faces.push(face);faceId=face.id;}selected=null;tool='add';wallChanged();$('#face-dialog').close();toast(edit?'Face atualizada.':'Foto adicionada. Toque nas agarras para cadastrar.');}catch(error){toast(error.message);}finally{button.disabled=false;}};
function renderRoutes(){const search=$('#route-search').value.toLocaleLowerCase('pt-BR'),routes=state.routes.filter(r=>r.snapshot.id===state.wall.id).filter(r=>r.name.toLocaleLowerCase('pt-BR').includes(search));$('#route-list').innerHTML=routes.length?routes.map(r=>`<article class="route-card"><span class="eyebrow">${r.kind==='via'?'VIA':'BOULDER'} / MONTAGEM ${r.snapshot.revision}</span><div class="grade">${esc(r.grade||'Sem grau')}</div><h3>${esc(r.name)}</h3><p>${Object.keys(r.assignments).length} agarras marcadas · ${r.snapshot.faces.length} faces<br>${r.snapshot.revision===state.wall.revision?'Montagem atual':'Montagem preservada'} · Grau sugerido</p><div class="card-actions"><button data-read="${r.id}" class="primary">Ler boulder →</button><button data-edit="${r.id}">Editar</button><button data-share="${r.id}" type="button">Compartilhar</button><button data-copy="${r.id}">Duplicar</button><button data-delete="${r.id}" aria-label="Excluir ${esc(r.name)}">Excluir</button></div></article>`).join(''):`<div class="route-empty"><h3>${state.routes.length?'Nenhum projeto encontrado.':'Seu primeiro projeto começa com uma agarra.'}</h3><p>${state.routes.length?'Tente outro nome.':'Cadastre as agarras do muro e use “Montar boulder”.'}</p></div>`;
 $$('[data-share]').forEach(b=>b.onclick=()=>shareRoute(state.routes.find(r=>r.id===b.dataset.share)));
 $$('[data-read]').forEach(b=>b.onclick=()=>{sessionId=b.dataset.read;sessionFace=null;switchView('session')});$$('[data-edit]').forEach(b=>b.onclick=()=>openRoute(b.dataset.edit));$$('[data-copy]').forEach(b=>b.onclick=()=>openRoute(b.dataset.copy,true));$$('[data-delete]').forEach(b=>b.onclick=async()=>{const r=state.routes.find(r=>r.id===b.dataset.delete);if(await confirmAction('Excluir este boulder?',`“${r.name}” e seus registros de tentativa serão removidos. Exporte um backup para preservar seu acervo.`)){state.routes=state.routes.filter(x=>x.id!==r.id);state.attempts=state.attempts.filter(x=>x.routeId!==r.id);persist();renderRoutes();renderCounts();}});
}
function openRoute(key=null,copy=false,generated=null){if(!key&&!generated&&!state.wall.holds.length){toast('Cadastre as agarras antes de montar um boulder.');switchView('wall');return;}const existing=state.routes.find(r=>r.id===key),wasOpen=$('#route-dialog').open,restorePosition=wasOpen?rememberPosition():null,previousRole=role,detailsOpen=$('#route-form details').open;if(!wasOpen)editorZoom=100;draft=generated?structuredClone(generated):existing?structuredClone(existing):{id:id(),name:'',kind:'boulder',scale:'V',grade:'',stance:'free',feet:'follow',smear:'no',finishSeconds:2,notes:'',assignments:{},snapshot:structuredClone(state.wall)};if(copy){draft.id=id();draft.name=(draft.name+' — cópia').slice(0,80);}const form=$('#route-form');form.reset();for(const key of ['name','kind','scale','grade','stance','feet','smear','finishSeconds','notes'])form.elements[key].value=draft[key];editorFace=routeFace(draft,faceId);role=wasOpen?previousRole:'hand';$('#route-dialog').classList.toggle('suggestion-preview',!!generated&&!generated.name.startsWith('On the Rock'));$('#route-dialog-title').textContent=generated?'Sua sugestão de boulder':existing&&!copy?'Editar boulder':'Montar boulder';$('#generation-note').hidden=!generated;$('#generation-note').textContent=generated?generated.notes.split('\n')[0]:'';$('#regenerate-route').hidden=!generated;$('#previous-suggestion').hidden=!generated||generated.name.startsWith('On the Rock');$('#previous-suggestion').disabled=generationIndex<=0;$('#edit-suggestion').hidden=!generated||generated.name.startsWith('On the Rock');$('#route-form details').open=wasOpen?detailsOpen:false;$('#route-error').textContent='';renderEditor();if(!wasOpen){$('#route-dialog').showModal();document.activeElement?.blur?.();$('#route-dialog-title').tabIndex=-1;$('#route-dialog-title').focus({preventScroll:true});}restorePosition?.();}
function renderEditor(){ const restorePosition=rememberPosition();$('#editor-zoom').value=editorZoom;tabs('#editor-faces',draft.snapshot.faces,editorFace,value=>{editorFace=value;renderEditor()});$('#route-tools').innerHTML=Object.entries(roleLabels).map(([key,label])=>`<button type="button" data-role="${key}" class="${key===role?'active':''}">${label}</button>`).join('');$$('[data-role]').forEach(b=>b.onclick=()=>{role=b.dataset.role;renderEditor()});board('#editor-stage',draft.snapshot,editorFace,{route:draft,dim:65,zoom:editorZoom,onHold:$('#route-dialog').classList.contains('suggestion-preview')?null:key=>{try{setRole(draft,key,role);$('#route-error').textContent='';renderEditor();}catch(error){$('#route-error').textContent=error.message;}}});$('#route-summary').textContent=`${Object.keys(draft.assignments).length} agarras marcadas. ${summaryHands(draft,'start')} · ${summaryHands(draft,'finish')}`;restorePosition();}
function summaryHands(r,kind){const get=s=>r.snapshot.holds.find(h=>r.assignments[h.id]?.includes(s));const left=get(kind+'L'),right=get(kind+'R'),label=kind==='start'?'Saída':'Final';return left&&right?left.id===right.id?`${label}: duas mãos em ${left.name}`:`${label}: E em ${left.name}, D em ${right.name}`:`${label}: faltam marcações`;}
$('#route-form').elements.feet.onchange=e=>{if(draft){draft.feet=e.target.value;renderEditor()}};
$('#route-form').elements.kind.onchange=e=>{$('#route-form').elements.scale.value=e.target.value==='via'?'Brasileira (via)':'V';};
$('#route-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);for(const key of ['name','kind','scale','grade','stance','feet','smear','notes'])draft[key]=f.get(key).trim();draft.finishSeconds=Number(f.get('finishSeconds'));const error=validateRoute(draft);if(error){$('#route-error').textContent=error;return;}const previous=state.routes.findIndex(r=>r.id===draft.id);if(previous>=0)state.routes[previous]=structuredClone(draft);else state.routes.push(structuredClone(draft));const saved=await persist();renderCounts();sessionId=draft.id;$('#route-dialog').close();switchView('routes');if(saved)toast('Boulder salvo com sua montagem.');};
function renderSession(){const localRoutes=state.routes.filter(r=>r.snapshot.id===state.wall.id);if(!localRoutes.some(r=>r.id===sessionId))sessionId=localRoutes[0]?.id;$('#session-route').innerHTML=localRoutes.map(r=>`<option value="${r.id}" ${r.id===sessionId?'selected':''}>${esc(r.name)} · ${esc(r.grade||'Sem grau')}</option>`).join('');const r=localRoutes.find(r=>r.id===sessionId);if(camera.active&&r)camera.changeRoute(r);$('#start-camera').disabled=!r;$('#previous-route').disabled=!r||localRoutes.length<2;$('#next-route').disabled=!r||localRoutes.length<2;if(!r){$('#session-faces').innerHTML='';$('#session-stage').innerHTML='<div class="empty-state"><h3>Nenhum boulder salvo.</h3><p>Monte um boulder para começar a sessão.</p></div>';$('#session-info').innerHTML='<h3>Sem boulder selecionado.</h3><button id="session-create" class="primary">Montar boulder</button>';$('#session-create').onclick=()=>openRoute();return;}
 if(!r.snapshot.faces.some(f=>f.id===sessionFace))sessionFace=routeFace(r,faceId);tabs('#session-faces',r.snapshot.faces,sessionFace,key=>{sessionFace=key;renderSession()});board('#session-stage',r.snapshot,sessionFace,{route:r,dim:Number($('#dim').value)});
 const logs=state.attempts.filter(a=>a.routeId===r.id),feetLabels={follow:'Seguem mãos + pés marcados',marked:'Somente pés marcados',free:'Todas as agarras do muro'};$('#session-info').innerHTML=`<div class="eyebrow">${r.kind==='via'?'VIA':'BOULDER'} / GRAU SUGERIDO</div><div class="stat">${esc(r.grade||'—')}</div><h3>${esc(r.name)}</h3><div class="info-list"><span>${esc(summaryHands(r,'start'))}</span><span>${esc(summaryHands(r,'finish'))}</span><span>Pés: <b>${feetLabels[r.feet]}</b></span><span>Saída: <b>${{free:'livre',sit:'sentado',stand:'em pé'}[r.stance]}</b></span><span>Final: <b>${r.finishSeconds} s de controle</b></span><span>Parede: ${r.smear==='yes'?'aderência permitida':'só agarras selecionadas'}</span></div>${r.notes?`<p style="white-space:pre-wrap">${esc(r.notes)}</p>`:''}<hr><span class="badge">${logs.length} tentativas</span><span class="badge">${logs.filter(a=>a.type==='send').length} encadenamentos</span><button id="log-attempt" class="quiet">+ Registrar tentativa</button><button id="log-send" class="primary">Encadenei ✓</button>${logs.length?'<button id="undo-attempt" class="text-button">Desfazer último registro</button>':''}<hr><p>Montagem ${r.snapshot.revision}${r.snapshot.revision!==state.wall.revision?' · diferente do cadastro atual. Confira o muro antes de usar.':'.'}</p><p>S / E / D = saída e mãos<br>M = mão · P = pé · F = final</p>`;
 $('#log-attempt').onclick=()=>logAttempt('attempt');$('#log-send').onclick=()=>logAttempt('send');if($('#undo-attempt'))$('#undo-attempt').onclick=()=>{const last=logs.at(-1);state.attempts=state.attempts.filter(a=>a.id!==last.id);persist();renderSession();};
}
function logAttempt(type){state.attempts.push({id:id(),routeId:sessionId,type,at:new Date().toISOString()});persist();renderSession();toast(type==='send'?'Encadenamento registrado.':'Tentativa registrada.');}
$$('[data-view]').forEach(b=>b.onclick=()=>switchView(b.dataset.view));$$('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());$('#add-face').onclick=addFace;$('#first-face').onclick=addFace;$('#tool-select').onclick=()=>{tool='select';renderWall()};$('#tool-add').onclick=()=>{tool='add';selected=null;renderWall()};$('#zoom').oninput=renderWall;
$('#undo').onclick=()=>{const wall=history.pop();if(wall){wall.revision=state.wall.revision+1;state.wall=wall;selected=null;persist();renderWall();renderCounts();}$('#undo').disabled=!history.length;};
$('#rename-wall').onclick=async()=>{const name=await askName('Renomear local',state.wall.name);if(name?.trim()){state.wall.name=name.trim().slice(0,80);persist();renderCounts();}};
$('#new-route').onclick=()=>openRoute();$('#route-search').oninput=renderRoutes;$('#session-route').onchange=e=>{sessionId=e.target.value;sessionFace=null;renderSession()};$('#dim').oninput=()=>{camera.dim=Number($('#dim').value)/100;renderSession()};
for(const [selector,step]of [['#previous-route',-1],['#next-route',1]])$(selector).onclick=()=>{const routes=state.routes.filter(r=>r.snapshot.id===state.wall.id),i=routes.findIndex(r=>r.id===sessionId);sessionId=routes[(i+step+routes.length)%routes.length]?.id;renderSession();};
$('#backup').onclick=()=>{const blob=new Blob([JSON.stringify(state)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`homeclimb-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exportado com fotos e boulders.');};
$('#restore').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>100*1024*1024)throw Error('Backup maior que 100 MB.');const imported=validateState(JSON.parse(await file.text()));if(!await confirmAction('Restaurar este backup?',`Ele contém ${imported.wall.faces.length} faces e ${imported.routes.length} boulders. Vai substituir o acervo deste aparelho. Exporte o atual se quiser guardá-lo.`))return;await persistence.catch(()=>{});await writeState(imported);if(storageFailed){location.reload();return;}state=imported;history=[];selected=null;faceId=null;sessionId=null;sessionFace=null;$('#undo').disabled=true;renderCounts();restoreNavigation();$('#save-state').textContent='Backup restaurado neste aparelho';toast('Acervo restaurado.');}catch(error){toast(`Não foi possível importar: ${error.message}`);}};

const holdDetection=createHoldDetection({onAccept:async(targetFaceId,candidates)=>{
 const targetFace=state.wall.faces.find(f=>f.id===targetFaceId);
 if(!targetFace)throw Error('Esta face não existe mais.');
 const additions=withoutExisting(candidates,state.wall.holds.filter(h=>h.faceId===targetFaceId),targetFace.aspect);
 if(!additions.length)throw Error('Estas agarras já estão cadastradas.');
 if(state.wall.holds.length+additions.length>5000)throw Error('O acervo comporta até 5000 agarras. Selecione menos sugestões.');
 checkpoint();const names=new Set(state.wall.holds.filter(h=>h.faceId===targetFaceId).map(h=>h.name));let number=1;
 for(const c of additions){while(names.has('A'+number))number++;const name='A'+number;names.add(name);state.wall.holds.push({id:id(),faceId:targetFaceId,x:c.x,y:c.y,radius:c.radius,contour:c.contour,name,quality:'unknown',type:'Não informado',color:'',direction:0,match:false});}
 faceId=targetFaceId;selected=state.wall.holds.at(-additions.length).id;tool='select';state.wall.revision++;
 const saved=await persist();renderWall();renderCounts();if(saved)toast(additions.length+' agarras adicionadas. Agora classifique qualidade e tipo.');
}});
$('#detect-holds').onclick=()=>{const face=state.wall.faces.find(f=>f.id===faceId);if(face)holdDetection.open(face,state.wall.holds.filter(h=>h.faceId===faceId));};

try{const saved=await readState();if(saved)state=validateState(saved);$('#save-state').textContent='Acervo local pronto';}catch(error){storageFailed=true;$('#save-state').textContent='Acervo protegido — recarregue ou importe um backup';toast('Não foi possível abrir o acervo. A edição foi bloqueada para preservar os dados existentes.');}
renderCounts();restoreNavigation();
if(storageFailed){$$('button,input,select,textarea').forEach(el=>{if(el.id!=='restore'&&!el.closest('#confirm-dialog'))el.disabled=true;});}
$('#editor-zoom').oninput=e=>{editorZoom=Number(e.target.value);renderEditor()};
function stopCamera(){camera.stop();$('#camera-panel').hidden=true;$('#session-stage').hidden=false;$('#stop-camera').disabled=true;}
$('#start-camera').onclick=async()=>{const route=state.routes.find(r=>r.id===sessionId);if(!route)return;$('#camera-panel').hidden=false;$('#session-stage').hidden=true;$('#stop-camera').disabled=false;$('#start-camera').disabled=true;await camera.start(route);$('#start-camera').disabled=false;};
$('#stop-camera').onclick=stopCamera;
window.addEventListener('pagehide',()=>camera.stop());
document.addEventListener('visibilitychange',()=>{if(document.hidden&&camera.active){camera.stop();$('#camera-status').textContent='Câmera desligada ao sair da página. Inicie novamente.';}});

function generatorInfo(){const face=state.wall.faces.find(f=>f.id===$('#generator-face').value);if(!face)return;const all=state.wall.holds.filter(h=>h.faceId===face.id),known=all.filter(h=>h.quality!=='unknown'&&!h.footOnly);$('#generator-info').textContent=known.length+' de '+all.length+' agarras classificadas para mãos. Agarras somente pé entram apenas nos apoios.';}
function openGenerator(){if(!state.wall.faces.length){toast('Adicione uma foto e cadastre as agarras primeiro.');switchView('wall');return;}const form=$('#generator-form');form.reset();$('#generator-face').innerHTML=state.wall.faces.map(f=>'<option value="'+f.id+'">'+esc(f.name)+'</option>').join('');$('#generator-face').value=faceId||state.wall.faces[0].id;const face=state.wall.faces.find(f=>f.id===$('#generator-face').value);form.elements.direction.value=face.angle>=65?'right':'up';$('#generator-error').textContent='';generatorInfo();$('#generator-dialog').showModal();}
async function runGenerator(config){const worker=new Worker('./generator-worker.js',{type:'module'});return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{worker.terminate();reject(Error('A busca demorou demais. Tente menos agarras.'));},20000);worker.onmessage=e=>{clearTimeout(timer);worker.terminate();e.data.error?reject(Error(e.data.error)):resolve(e.data.result);};worker.onerror=()=>{clearTimeout(timer);worker.terminate();reject(Error('Não foi possível abrir o gerador. Confira se os arquivos generator.js e generator-worker.js foram publicados.'));};worker.postMessage({wall:state.wall,options:config});});}
async function suggest(config){const result=await runGenerator(config);lastGeneration=config;openRoute(null,false,result.route);$('#generation-note').textContent=result.explanation+(result.ignored?' '+result.ignored+' agarras sem classificação foram ignoradas.':'');return result;}
$('#generate-route').onclick=openGenerator;$('#wall-generate').onclick=openGenerator;
$('#generator-face').onchange=()=>{generatorInfo();const face=state.wall.faces.find(f=>f.id===$('#generator-face').value);$('#generator-form').elements.direction.value=face.angle>=65?'right':'up';};
$('#generator-form').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.currentTarget),button=$('#generate-submit');button.disabled=true;button.textContent='Buscando uma sequência…';$('#generator-error').textContent='';try{const config={faceId:data.get('faceId'),target:Number(data.get('target')),count:Number(data.get('count')),reach:Number(data.get('reach')),direction:data.get('direction'),startBand:Number(data.get('startBand')),finishBand:Number(data.get('finishBand'))};const result=await runGenerator(config);if(!$('#generator-dialog').open)return;lastGeneration=config;generationHistory=[structuredClone(result.route)];generationIndex=0;$('#generator-dialog').close();openRoute(null,false,result.route);$('#generation-note').textContent=result.explanation+(result.ignored?' '+result.ignored+' agarras sem classificação foram ignoradas.':'');}catch(error){$('#generator-error').textContent=error.message;}finally{button.disabled=false;button.textContent='Gerar sugestão';}};
$('#regenerate-route').onclick=async()=>{if(!lastGeneration)return;const b=$('#regenerate-route'),currentDraft=draft.id;b.disabled=true;try{let route;if(generationIndex<generationHistory.length-1){route=structuredClone(generationHistory[++generationIndex]);}else{const result=await runGenerator(lastGeneration);if(!$('#route-dialog').open||draft.id!==currentDraft)return;route=result.route;generationHistory.push(structuredClone(route));if(generationHistory.length>8)generationHistory.shift();generationIndex=generationHistory.length-1;}openRoute(null,false,route);$('#previous-suggestion').disabled=generationIndex<=0;}catch(error){if($('#route-dialog').open)$('#route-error').textContent=error.message;}finally{b.disabled=false;}};
$('#previous-suggestion').onclick=()=>{if(generationIndex<=0)return;openRoute(null,false,generationHistory[--generationIndex]);$('#previous-suggestion').disabled=generationIndex<=0;};
$('#edit-suggestion').onclick=()=>{$('#route-dialog').classList.toggle('suggestion-preview');renderEditor();};


const context=document.modelContext;if(context?.registerTool){try{await context.registerTool({name:'list_homeclimb_routes',description:'Lista os boulders salvos neste aparelho.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({routes:state.routes.map(r=>({id:r.id,name:r.name,grade:r.grade}))})});await context.registerTool({name:'open_homeclimb_route',description:'Abre a leitura na foto de um boulder existente, sem registrar tentativa.',inputSchema:{type:'object',properties:{routeId:{type:'string'}},required:['routeId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(!input||typeof input.routeId!=='string'||!state.routes.some(r=>r.id===input.routeId))throw Error('Boulder não encontrado.');sessionId=input.routeId;sessionFace=null;switchView('session');return {opened:true,routeId:sessionId};}});}catch{console.info('Integração de ferramentas indisponível.');}}


$('#wall-manual').onclick=()=>openRoute();

const rock=createOnRock({getWall:()=>state.wall,getFace:()=>faceId,processPhoto,onRoute:route=>{lastGeneration=null;openRoute(null,false,route);editorFace=route.snapshot.holds.find(h=>route.assignments[h.id])?.faceId;renderEditor();$('#regenerate-route').hidden=true;}});
$('#wall-rock').onclick=()=>{if(!state.wall.holds.length){toast('Cadastre as agarras do seu muro primeiro.');return;}rock.open();};


function rememberNavigation(){try{sessionStorage.setItem('homeclimb-navigation',JSON.stringify({view,faceId,selected,sessionId,sessionFace,zoom:$('#zoom').value}));}catch{}}
function restoreNavigation(){let saved;try{saved=JSON.parse(sessionStorage.getItem('homeclimb-navigation'));}catch{}if(saved){faceId=state.wall.faces.some(f=>f.id===saved.faceId)?saved.faceId:null;selected=state.wall.holds.some(h=>h.id===saved.selected&&h.faceId===faceId)?saved.selected:null;sessionId=saved.sessionId;sessionFace=saved.sessionFace;$('#zoom').value=Math.max(100,Math.min(300,Number(saved.zoom)||100));}switchView(['wall','routes','session'].includes(saved?.view)?saved.view:'wall');}
window.addEventListener('pagehide',rememberNavigation);document.addEventListener('click',()=>queueMicrotask(rememberNavigation));

function renderLocationSelector(){const select=$('#location-select');select.replaceChildren(...locations(state).map(w=>{const o=document.createElement('option');o.value=w.id;o.textContent=w.name;return o;}));select.value=state.wall.id;}
function changedLocation(){stopCamera();selected=null;faceId=state.wall.faces[0]?.id;history=[];generationHistory=[];generationIndex=-1;lastGeneration=null;sessionId=null;sessionFace=null;$('#undo').disabled=true;persist();renderCounts();switchView('wall');}
$('#location-select').onchange=e=>{selectLocation(state,e.target.value);changedLocation();};
$('#add-location').onclick=async()=>{const name=await askName('Novo local');if(!name?.trim())return;try{addLocation(state,name);changedLocation();}catch(error){toast(error.message);}};
async function shareRoute(route){const payload=JSON.stringify(exportBoulder(route)),file=new File([payload],'homeclimb-boulder.json',{type:'application/json'});try{if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:route.name});return;}}catch(error){if(error.name==='AbortError')return;}const url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Arquivo do boulder pronto para enviar. Inclui a foto da face.');}
$('#receive-boulder').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>100*1024*1024)throw Error('Arquivo maior que 100 MB.');const data=JSON.parse(await file.text()),incoming=readBoulder(data);if(!await confirmAction('Receber boulder?',incoming.name+' · '+incoming.snapshot.name+'. Será adicionado ao acervo sem substituir seus muros.'))return;const route=importBoulder(state,data);selectLocation(state,route.snapshot.id);faceId=null;selected=null;history=[];$('#undo').disabled=true;lastGeneration=null;generationHistory=[];generationIndex=-1;sessionId=route.id;sessionFace=null;await persist();renderCounts();switchView('session');toast('Boulder recebido. A montagem original foi preservada.');}catch(error){toast(error.message);}};
